package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_verifyNonDup_TriageGen1Test {

    private CreatorCollector collector;
    private BeanDescription beanDesc;
    private MapperConfig<?> config;

    // Accessor for protected method
    private void invokeVerifyNonDup(AnnotatedWithParams newOne, int typeIndex, boolean explicit) throws Exception {
        Method method = CreatorCollector.class.getDeclaredMethod("verifyNonDup", AnnotatedWithParams.class, int.class, boolean.class);
        method.setAccessible(true);
        method.invoke(collector, newOne, typeIndex, explicit);
    }

    // Accessor for protected field _creators to verify state
    private AnnotatedWithParams getCreatorAt(int typeIndex) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField("_creators");
        field.setAccessible(true);
        AnnotatedWithParams[] creators = (AnnotatedWithParams[]) field.get(collector);
        return creators[typeIndex];
    }

    @Before
    public void setUp() {
        beanDesc = mock(BeanDescription.class);
        config = mock(MapperConfig.class);
        collector = new CreatorCollector(beanDesc, config);
    }

    @Test
    public void testFirstTimeAddition() throws Exception {
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        invokeVerifyNonDup(newOne, 0, false);

        assertTrue(collector.hasDefaultCreator());
        assertEquals(newOne, getCreatorAt(0));
    }

    @Test
    public void testFirstTimeAdditionExplicit() throws Exception {
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        invokeVerifyNonDup(newOne, 1, true);

        assertEquals(newOne, getCreatorAt(1));
        // Verify explicit mask bit is set via reflection or side effect if possible
        // Since we can't easily check _explicitCreators without reflection, we trust the logic flow
    }

    @Test
    public void testSkipWhenOldIsExplicitAndNewIsNot() throws Exception {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // Set old one as explicit
        invokeVerifyNonDup(oldOne, 0, true);

        // Try to add new one (not explicit)
        invokeVerifyNonDup(newOne, 0, false);

        // Should still be the old one
        assertEquals(oldOne, getCreatorAt(0));
    }

    @Test
    public void testBothExplicitTriggersVerify() throws Exception {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        when(oldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(newOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(oldOne.getRawParameterType(0)).thenReturn(String.class);
        when(newOne.getRawParameterType(0)).thenReturn(Integer.class); // Different type

        invokeVerifyNonDup(oldOne, 0, true);

        try {
            invokeVerifyNonDup(newOne, 0, true);
            fail("Should have thrown IllegalArgumentException due to conflicting types");
        } catch (Exception e) {
            assertTrue(e.getCause() instanceof IllegalArgumentException);
            assertTrue(e.getCause().getMessage().contains("Conflicting"));
        }
    }

    @Test
    public void testNewTypeIsMoreGeneric_KeepOld() throws Exception {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // Use same class to pass the (oldOne.getClass() == newOne.getClass()) check
        // But different parameter types
        when(oldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(newOne.getClass()).thenReturn(AnnotatedWithParams.class);

        // oldType = Object (generic), newType = String (specific)
        when(oldOne.getRawParameterType(0)).thenReturn(Object.class);
        when(newOne.getRawParameterType(0)).thenReturn(String.class);

        invokeVerifyNonDup(oldOne, 0, false);
        invokeVerifyNonDup(newOne, 0, false);

        // newType (String) is assignable from oldType (Object)? No. 
        // Wait, logic: if (newType.isAssignableFrom(oldType)) -> new is more generic.
        // If oldType is Object, newType is String. String.isAssignableFrom(Object) is false.
        // Re-reading logic: if (newType.isAssignableFrom(oldType)) { return; } 
        // This means if new is more generic (e.g., new is Object, old is String), keep old.

        // Let's adjust: newType = Object, oldType = String.
        when(oldOne.getRawParameterType(0)).thenReturn(String.class);
        when(newOne.getRawParameterType(0)).thenReturn(Object.class);

        invokeVerifyNonDup(oldOne, 0, false);
        invokeVerifyNonDup(newOne, 0, false);

        assertEquals(oldOne, getCreatorAt(0));
    }

    @Test
    public void testNewTypeIsMoreSpecific_Override() throws Exception {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        when(oldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(newOne.getClass()).thenReturn(AnnotatedWithParams.class);

        // oldType = Object, newType = String. String is more specific.
        when(oldOne.getRawParameterType(0)).thenReturn(Object.class);
        when(newOne.getRawParameterType(0)).thenReturn(String.class);

        invokeVerifyNonDup(oldOne, 0, false);
        invokeVerifyNonDup(newOne, 0, false);

        assertEquals(newOne, getCreatorAt(0));
    }

    @Test
    public void testDifferentClasses_NoVerify() throws Exception {
        // If classes are different, it skips the deep type check and just overrides
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // Force different classes
        when(oldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(newOne.getClass()).thenReturn(Mockito.spy(AnnotatedWithParams.class).getClass()); 
        // In real JVM, we'd use actual subclasses. Here we simulate via mock behavior if possible,
        // but since it's a direct == check, let's use real distinct classes if possible.

        class SubParam extends AnnotatedWithParams {
            public SubParam(AnnotatedWithParams p) { super(p); } // dummy
            @Override public Class<?> getRawParameterType(int i) { return String.class; }
        }

        AnnotatedWithParams subOne = new SubParam(null);

        invokeVerifyNonDup(oldOne, 0, false);
        invokeVerifyNonDup(subOne, 0, false);

        assertEquals(subOne, getCreatorAt(0));
    }
}

// Helper to allow instantiation of mock-like objects for class comparison
class AnnotatedWithParamsMock extends AnnotatedWithParams {
    public AnnotatedWithParamsMock(AnnotatedWithParams p) { super(p); }
    @Override public Class<?> getRawParameterType(int i) { return Object.class; }
}
